UPDATE knowledge_cards SET
        title=#{title},card_type=#{cardType},content=#{content},tags=#{tags,typeHandler=org.apache.ibatis.type.ArrayTypeHandler},status=#{status},revision=revision+1,updated_by=#{actorId},updated_at=CURRENT_TIMESTAMP
        WHERE id=#{id} AND repo_id=#{repositoryId}
